cat > $d/LayerDependencyTests.cs <<'E'
using System.Reflection;
using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical concerns that belong to Infrastructure only.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    private static Assembly Of(string name) => Assembly.Load(name);

    private static void AssertNoDependencies(string assembly, string[] forbidden)
    {
        var result = Types.InAssembly(Of(assembly)).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful,
            $"{assembly} must not depend on {string.Join(", ", forbidden)}. Offenders: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }

    [Fact]
    public void Domain_depends_on_no_other_layer_and_no_technical_detail() =>
        AssertNoDependencies(DomainNs, [ApplicationNs, InfrastructureNs, .. TechnicalNamespaces]);

    [Fact]
    public void Application_depends_on_neither_infrastructure_nor_technical_detail() =>
        AssertNoDependencies(ApplicationNs, [InfrastructureNs, .. TechnicalNamespaces]);
}
E
dotnet add $d package NetArchTest.Rules 2>&1 | tail -3; git diff --stat; git status --short

